er_id' => $userId)));        $this->set('menus',$this->Menu->menuItems(AuthComponent::user('role'),null,$societyData));        $this->Auth->allow(['privacy_policy','refund_policy','termandcondition']);    }    public function isAuthorized($user) {        // Here is where we should verify the role and give access based on role        return true;    }    public function forceSSL() {        return $this->redirect('https://' . env('SERVER_NAME') . $this->here);    }}